import{_ as a,o as t,c as s,a1 as o}from"./chunks/framework.CiMD_7j0.js";const p=JSON.parse('{"title":"Operations & Troubleshooting","description":"","frontmatter":{"AIGC":{"ContentProducer":"001191110102MAD55U9H0F10002","ContentPropagator":"001191110102MAD55U9H0F10002","Label":"1","ProduceID":"54643897-2147-4b3c-b098-87fb372d09fe","PropagateID":"54643897-2147-4b3c-b098-87fb372d09fe","ReservedCode1":"4a845224-e884-4686-b988-b541e2a15a78","ReservedCode2":"4a845224-e884-4686-b988-b541e2a15a78"}},"headers":[],"relativePath":"en/guide/python/operations.md","filePath":"en/guide/python/operations.md","lastUpdated":null}'),n={name:"en/guide/python/operations.md"};function r(i,e,d,l,c,u){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="operations-troubleshooting" tabindex="-1">Operations &amp; Troubleshooting <a class="header-anchor" href="#operations-troubleshooting" aria-label="Permalink to &quot;Operations &amp; Troubleshooting&quot;">​</a></h1><h2 id="logs" tabindex="-1">Logs <a class="header-anchor" href="#logs" aria-label="Permalink to &quot;Logs&quot;">​</a></h2><p>ApeAdmin generates a request ID for every API request and records the method, path, status code, latency, user and client info in <code>sys_log</code>. MCP calls have a separate <code>McpAuditLog</code>; you can inspect tool results and failure reasons in the admin panel.</p><p>When debugging plugin issues, check in order: startup logs, the plugin&#39;s <code>runtime_state</code> / <code>last_error</code>, the <code>sys_log</code> entries for the request ID, and the API responses in the browser Network tab.</p><h2 id="common-issues" tabindex="-1">Common Issues <a class="header-anchor" href="#common-issues" aria-label="Permalink to &quot;Common Issues&quot;">​</a></h2><h3 id="menu-returns-404" tabindex="-1">Menu returns 404 <a class="header-anchor" href="#menu-returns-404" aria-label="Permalink to &quot;Menu returns 404&quot;">​</a></h3><p>Check that the menu <code>component</code> resolves to a <code>.vue</code> file of the same name under <code>frontend/src/views</code> (case-sensitive). Then sign out and reload the user menus.</p><h3 id="plugin-shows-enabled-but-apis-are-missing" tabindex="-1">Plugin shows enabled but APIs are missing <a class="header-anchor" href="#plugin-shows-enabled-but-apis-are-missing" aria-label="Permalink to &quot;Plugin shows enabled but APIs are missing&quot;">​</a></h3><p>Check whether the plugin&#39;s <code>register(app)</code> succeeded and whether there are duplicate prefixes. If needed, disable and re-enable the plugin; never delete a running plugin directory directly.</p><h3 id="ai-document-analysis-fails" tabindex="-1">AI document analysis fails <a class="header-anchor" href="#ai-document-analysis-fails" aria-label="Permalink to &quot;AI document analysis fails&quot;">​</a></h3><p>Confirm the DeepSeek API Key, model and network access are configured in the admin panel. Check whether the upload exceeds the size/file-count limits or contains path traversal, symlinks or encrypted files.</p><h3 id="website-assets-404" tabindex="-1">Website assets 404 <a class="header-anchor" href="#website-assets-404" aria-label="Permalink to &quot;Website assets 404&quot;">​</a></h3><p>Confirm Apehub_web is enabled and the <code>/apehub-web</code> static mount exists. Plugin packages must include <code>static/docs-portal</code> but not the dev-only <code>node_modules</code>.</p><h2 id="production-checklist" tabindex="-1">Production Checklist <a class="header-anchor" href="#production-checklist" aria-label="Permalink to &quot;Production Checklist&quot;">​</a></h2><ul><li>Change the default admin password and restrict admin access.</li><li>Use environment variables or a secret manager for database, JWT, SMTP, AI and payment credentials.</li><li>Use migration scripts instead of relying on auto table creation.</li><li>Configure backup and access control for the uploads directory.</li><li>Verify the disable, re-enable, upgrade and uninstall flows; confirm no menu, route, database or file resources are left behind.</li></ul>',15)])])}const b=a(n,[["render",r]]);export{p as __pageData,b as default};
